input.source:
from $.inventory.items.*
where .qty >= 2 and .active == true
select { sku = .sku qty = .qty }

from $.inventory.items.*
where startsWith(.sku, "A") or startsWith(.sku, "B")
select { code = lower(.sku) category = upper(.category) label = concat("item:", .sku) }

from $.inventory.items.*
where endsWith(.sku, "00")
select { sku = .sku code = lower(.sku) category = upper(.category) label = concat("item:", .sku) }

from path($.<"params">.source)
where isValue(path($.<"params">.active))
select path($.<"params">.field)

from $.inventory.items.*
where .qty >= 4
select { sku = .sku category = resolveChild($.inventory.categoryLabels, .category) }

from $.inventory.items.*
where .qty >= 4
select { sku = .sku category = resolveChild($.inventory.categoryLabels, .category) status = fallback(.status, "missing") }
